import React, { useEffect } from 'react';
import { NavLink, Outlet, useLocation } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { Bell, Home, Package, User, Wifi, WifiOff } from 'lucide-react';
import { useCourier } from '../lib/store';
import { Logo, Toaster, cn } from './ui';

const BottomNav = () => {
  const { t } = useTranslation();
  const { orders } = useCourier();
  const newCount = orders.filter((o) => o.status === 'new').length;
  const activeCount = orders.filter((o) => ['accepted', 'picked_up', 'on_the_way'].includes(o.status)).length;
  const items = [
    { to: '/', label: 'dashboard', icon: Home },
    { to: '/orders', label: 'orders', icon: Package, badge: newCount + activeCount },
    { to: '/profile', label: 'profile', icon: User },
  ];
  return (
    <nav className="fixed inset-x-0 bottom-4 z-50 px-5">
      <div className="glass-bar mx-auto grid max-w-md grid-cols-3 rounded-[1.4rem] px-3 py-1.5 shadow-soft">
        {items.map((item) => (
          <NavLink
            key={item.to}
            to={item.to}
            end={item.to === '/'}
            className={({ isActive }) => cn('relative flex flex-col items-center gap-1 rounded-2xl py-2 text-[10px] font-bold transition', isActive ? 'text-white' : 'text-[var(--muted)]')}
          >
            {({ isActive }) => (
              <>
                {isActive && <span className="accent-bg absolute inset-1 rounded-2xl shadow-glow" />}
                <span className="relative">
                  <item.icon size={19} />
                  {!!item.badge && <span className="absolute -right-2 -top-1.5 flex h-4 min-w-4 items-center justify-center rounded-full bg-rose-500 px-1 text-[8px] font-black text-white shadow">{item.badge}</span>}
                </span>
                <span className="relative font-extrabold">{t(item.label)}</span>
              </>
            )}
          </NavLink>
        ))}
      </div>
    </nav>
  );
};

export const Layout = () => {
  const { t } = useTranslation();
  const { pathname } = useLocation();
  const { online, setOnline, courier } = useCourier();

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'instant' });
  }, [pathname]);

  useEffect(() => {
    const saved = localStorage.getItem('maxshop-courier-theme');
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    document.documentElement.classList.toggle('dark', saved ? saved === 'dark' : prefersDark);
  }, []);

  return (
    <div className="aurora flex min-h-screen flex-col">
      <header className="sticky top-0 z-40">
        <div className="mx-auto mt-3 flex h-14 w-full max-w-2xl items-center justify-between rounded-2xl px-4">
          <Logo />
          <div className="flex items-center gap-2">
            <button
              onClick={() => setOnline(!online)}
              className={cn('flex items-center gap-1.5 rounded-full px-2.5 py-1.5 text-[10px] font-extrabold transition', online ? 'glass-bar text-brand-700 dark:text-brand-300 shadow-sm' : 'border bg-[var(--surface-2)] text-[var(--muted)]')}
            >
              {online ? <Wifi size={12} /> : <WifiOff size={12} />}
              {online ? t('online') : t('offline')}
              <span className="relative flex h-2 w-2">
                {online && <span className="absolute inline-flex h-full w-full animate-ping-slow rounded-full bg-brand-500" />}
                <span className={cn('relative h-2 w-2 rounded-full', online ? 'bg-brand-500' : 'bg-[var(--muted)]')} />
              </span>
            </button>
            <button className="icon-btn relative h-9 w-9 transition"><Bell size={15} /><span className="absolute right-2.5 top-2 h-1.5 w-1.5 rounded-full bg-rose-500" /></button>
            <span className="accent-bg flex h-9 w-9 items-center justify-center rounded-2xl text-[11px] font-extrabold text-white shadow-glow">{courier.name.split(' ').map((n) => n[0]).slice(0, 2).join('')}</span>
          </div>
        </div>
      </header>

      <main className="mx-auto w-full max-w-2xl flex-1 px-5 pb-36 pt-3">
        <Outlet />
      </main>

      <BottomNav />
      <Toaster />
    </div>
  );
};
